def build_input_test(sentences ,word2index):
    X =[]
    for tokens in sentences:
        curx = [word2index['_pad_']]
        for token in tokens:
            if token in word2index:
                curx.append(word2index[token])
            else:
                curx.append(1)
        X.append(torch.tensor(curx))
    return X

class sentimentdata(Dataset):
    def __init__(self , X, Y, max_len=40):
        self.X = X
        self.Y = Y
        self.max_len = max_len
    def __len__(self):
        return len(self.X)
    def __getitem__(self , index):
        x = self.X[index]
        y = self.Y[index]

        # Pad or truncate x to max_len
        if len(x) >= self.max_len:
            x = x[:self.max_len]
        else:
            x_padded = torch.zeros(self.max_len, dtype=x.dtype)
            x_padded[:len(x)] = x
            x = x_padded

        return x, y

